package com.novalearn.application.child;
import com.novalearn.domain.child.Avatar; import com.novalearn.domain.child.ChildProfile; import com.novalearn.domain.child.GradeLevel; import org.junit.jupiter.api.Test; import java.time.LocalDate; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.ArgumentMatchers.eq; import static org.mockito.Mockito.*;
class ChildServiceTest {
 @Test void creates_trimmed_child_profile(){ChildProfileRepository repository=mock(ChildProfileRepository.class);when(repository.save(any())).thenAnswer(i->i.getArgument(0));ChildService service=new ChildService(repository);UUID parent=UUID.randomUUID();ChildProfile child=service.create(parent,"  Maya  ",LocalDate.of(2020,1,1));assertThat(child.parentId()).isEqualTo(parent);assertThat(child.displayName()).isEqualTo("Maya");}
 @Test void defaultsGradeLevelAndAvatarWhenNotProvided(){ChildProfileRepository repository=mock(ChildProfileRepository.class);when(repository.save(any())).thenAnswer(i->i.getArgument(0));ChildService service=new ChildService(repository);ChildProfile child=service.create(UUID.randomUUID(),"Maya",LocalDate.of(2020,1,1));assertThat(child.gradeLevel()).isEqualTo(GradeLevel.GRADE_1);assertThat(child.avatar()).isEqualTo(Avatar.FOX);assertThat(child.learningPreferences()).isEmpty();}
 @Test void lists_only_profiles_owned_by_the_parent(){ChildProfileRepository repository=mock(ChildProfileRepository.class);ChildService service=new ChildService(repository);UUID parent=UUID.randomUUID();List<ChildProfile> expected=List.of(new ChildProfile(UUID.randomUUID(),parent,"Maya",LocalDate.of(2020,1,1),GradeLevel.GRADE_1,Avatar.FOX,Set.of()));when(repository.findByParentId(parent)).thenReturn(expected);assertThat(service.list(parent)).containsExactlyElementsOf(expected);}
 @Test void updates_name_and_grade_and_keeps_other_fields(){ChildProfileRepository repository=mock(ChildProfileRepository.class);when(repository.save(any())).thenAnswer(i->i.getArgument(0));ChildService service=new ChildService(repository);UUID parent=UUID.randomUUID();UUID id=UUID.randomUUID();ChildProfile existing=new ChildProfile(id,parent,"Leo",LocalDate.of(2020,7,1),GradeLevel.KINDERGARTEN,Avatar.OWL,Set.of());when(repository.belongsToParent(id,parent)).thenReturn(true);when(repository.findById(id)).thenReturn(Optional.of(existing));ChildProfile updated=service.update(parent,id," Suhansh ",null,GradeLevel.PRE_K,null);assertThat(updated.id()).isEqualTo(id);assertThat(updated.displayName()).isEqualTo("Suhansh");assertThat(updated.gradeLevel()).isEqualTo(GradeLevel.PRE_K);assertThat(updated.birthDate()).isEqualTo(LocalDate.of(2020,7,1));assertThat(updated.avatar()).isEqualTo(Avatar.OWL);}
 @Test void refuses_to_update_another_parents_child(){ChildProfileRepository repository=mock(ChildProfileRepository.class);ChildService service=new ChildService(repository);UUID id=UUID.randomUUID();when(repository.belongsToParent(eq(id),any())).thenReturn(false);assertThatThrownBy(()->service.update(UUID.randomUUID(),id,"X",null,null,null)).isInstanceOf(com.novalearn.application.common.ChildNotFoundException.class);verify(repository,never()).save(any());}
}
